insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Este Decreto regulamenta a Lei da Carteira de Identidade, para estabelecer os procedimentos e requisitos de expedição da Carteira de Identidade pelos órgãos de identificação dos Estados e do Distrito Federal, e a Lei do Registro de Identidade Civil, para estabelecer o Serviço de Identificação do Cidadão como o Sistema Nacional de Registro de Identificação Civil.', '["Regulamenta a Lei nº 7.116, de 29 de agosto de 1983.","Regulamenta a Lei nº 9.454, de 7 de abril de 1997.","Serviço de Identificação do Cidadão como sistema nacional."]'::jsonb, '["ATUALIZAÇÃO: a menção ao Serviço de Identificação do Cidadão como sistema nacional foi ajustada pelo Decreto nº 11.797, de 2023.","É um DECRETO regulamentar."]'::jsonb, 'O Decreto detalha como os Estados expedem a nova carteira de identidade.', '["Assertiva que trata o Decreto como lei ordinária erra: ele regulamenta as leis."]'::jsonb, '[]'::jsonb, '["Lei da Carteira de Identidade"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'cin' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Carteira de Identidade tem fé pública, validade em todo o território nacional e constitui documento de identidade válido para todos os fins legais. Ela é única em âmbito nacional, e sua expedição em ente federativo distinto do local da primeira via será considerada segunda via do documento.', '["Fé pública e validade nacional.","Documento válido para todos os fins legais.","Única em âmbito nacional.","Expedição em outro ente é segunda via."]'::jsonb, '["Mudar de Estado e pedir nova identidade gera SEGUNDA VIA."]'::jsonb, 'Quem muda de Estado e emite a identidade lá recebe segunda via do mesmo documento.', '["Assertiva que considera nova primeira via a emissão em outro Estado erra: é segunda via."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'cin' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Carteira de Identidade adota o número de inscrição no CPF como registro geral nacional. Se o requerente não estiver inscrito no CPF, o órgão de identificação fará, de ofício, a inscrição, conforme as normas da Receita Federal.', '["CPF como registro geral nacional.","Inscrição de ofício no CPF pelo órgão de identificação."]'::jsonb, '["ATUALIZAÇÃO: o parágrafo único foi incluído pelo Decreto nº 11.797, de 2023.","O CPF substitui o antigo número de RG."]'::jsonb, 'O órgão inscreve no CPF quem ainda não tem o número.', '["Assertiva que mantém o RG como número distinto do CPF erra: o CPF é o registro geral."]'::jsonb, '[]'::jsonb, '["Lei do CPF"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'cin' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para expedir a Carteira de Identidade, somente será exigida a certidão de nascimento ou de casamento, em formato físico ou digital. Em dúvida fundamentada sobre a autenticidade, o órgão poderá exigir certidão expedida nos últimos seis meses ou documento de identificação civil. Na alteração de dados biográficos, o requerente apresenta certidão que a comprove. O naturalizado apresenta o certificado de naturalização e o português com igualdade de direitos apresenta o ato de outorga. A expedição depende de solicitação e de atualização e conferência dos dados biométricos. A documentação é registrada pelo órgão. O requerente pode pedir a inclusão de informações de saúde. É vedada a formulação de exigências não previstas no Decreto.', '["Somente a certidão de nascimento ou de casamento.","Dúvida fundamentada: certidão recente ou outro documento civil.","Naturalizado e português com igualdade têm documentos próprios.","Dados biométricos atualizados e conferidos.","Vedadas exigências não previstas."]'::jsonb, '["Proibição de exigências ADICIONAIS."]'::jsonb, 'O órgão não pode exigir comprovante de residência para emitir a identidade.', '["Assertiva que permite exigir comprovante de residência erra: o §8º veda exigências não previstas."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'cin' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Carteira de Identidade será expedida em papel de segurança ou em cartão de policarbonato, e em formato digital, conforme os modelos dos Anexos I, II e III. A versão digital é expedida no mesmo processo de identificação e gerada após a entrega do documento em formato físico.', '["Formatos: papel de segurança, cartão de policarbonato e digital.","Modelos nos Anexos I, II e III.","A versão digital nasce no mesmo processo, após o documento físico."]'::jsonb, '["Versão digital depois da física."]'::jsonb, 'O cidadão recebe o cartão e, em seguida, a versão digital.', '["Assertiva que dispensa o documento físico para gerar o digital erra."]'::jsonb, '[]'::jsonb, '["Anexos I a III"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'cin' and u.unit_key = 'art-5'
