select u.id, u.content_sha256, 'A Carteira de Identidade atenderá aos requisitos de segurança, integridade e interoperabilidade estabelecidos pela Câmara-Executiva Federal de Identificação do Cidadão (Cefic).', '["Requisitos de segurança, integridade e interoperabilidade.","Definidos pela Cefic."]'::jsonb, '["Quem estabelece os requisitos é a Cefic."]'::jsonb, 'A Cefic fixa o padrão de segurança da carteira digital.', '["Assertiva que atribui a definição dos requisitos a cada Estado erra: é da Cefic."]'::jsonb, '[{"termo":"Cefic","significado":"Câmara-Executiva Federal de Identificação do Cidadão."}]'::jsonb, '["Decreto do Serviço de Identificação do Cidadão"]'::jsonb, 'under_review', 'claude'
