insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Carteira de Identidade conterá as Armas da República e as inscrições República Federativa do Brasil e Governo Federal; a identificação do ente e do órgão expedidor; o número do registro geral nacional; nome, filiação, sexo, nacionalidade, local e data de nascimento; o número único da matrícula de nascimento ou casamento; a fotografia no formato 3x4 cm, no padrão da OACI, a assinatura e a impressão digital do polegar direito; a assinatura do dirigente do órgão; a expressão Válida em todo o território nacional; a data de validade, local e data de expedição; o QR code; e a zona de leitura mecânica. Essas informações constarão do documento digital.', '["Elementos obrigatórios (incisos I a XII).","Foto 3x4 cm no padrão da OACI.","Impressão digital do polegar direito.","QR code e zona de leitura mecânica.","Constam também do documento digital."]'::jsonb, '["Impressão do polegar DIREITO.","QR code e zona de leitura mecânica seguem padrões internacionais."]'::jsonb, 'O QR code permite verificar a autenticidade da carteira.', '["Assertiva que prevê a impressão do polegar esquerdo erra: é do polegar direito."]'::jsonb, '[{"termo":"OACI","significado":"Organização da Aviação Civil Internacional."}]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
