insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Tribunal Superior Eleitoral garantirá aos Poderes Executivo e Legislativo da União, dos Estados, do Distrito Federal e dos Municípios acesso gratuito à base de dados da ICN, exceto quanto às informações eleitorais. O Poder Executivo dos entes poderá integrar aos seus bancos as informações da base, com exceção dos dados biométricos. Ato do TSE disporá sobre a integração dos registros biométricos pelas Polícias Federal e Civil, com exclusividade, às suas bases de dados.', '["Acesso gratuito aos Poderes Executivo e Legislativo dos entes.","Excluídas as informações eleitorais.","Executivos podem integrar a base, exceto biometria.","Biometria: integração exclusiva das Polícias Federal e Civil."]'::jsonb, '["Dados biométricos: só as polícias Federal e Civil integram às suas bases."]'::jsonb, 'A Polícia Civil integra os registros biométricos à sua base, conforme ato do TSE.', '["Assertiva que permite a integração da biometria por qualquer Executivo erra: é exclusiva das polícias."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'icn' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É vedada a comercialização, total ou parcial, da base de dados da ICN. Isso não impede o serviço de conferência de dados que envolvam a biometria prestado a particulares, a ser realizado exclusivamente pelo Tribunal Superior Eleitoral.', '["Vedada a comercialização da base.","Conferência de dados biométricos a particulares: só pelo TSE."]'::jsonb, '["O §1º foi vetado.","A conferência a particulares é prestada exclusivamente pelo TSE."]'::jsonb, 'Um banco paga ao TSE pela conferência da biometria do cliente, sem comprar a base.', '["Assertiva que permite vender a base a particulares erra: é vedado."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'icn' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É criado o Comitê Gestor da ICN, composto por três representantes do Poder Executivo federal, três do Tribunal Superior Eleitoral, um da Câmara dos Deputados, um do Senado Federal e um do Conselho Nacional de Justiça. Compete-lhe recomendar o padrão biométrico, o padrão e os documentos para o DNI, os parâmetros do serviço de conferência de dados e as diretrizes do Fundo da ICN; orientar a interoperabilidade entre o Executivo federal e a Justiça Eleitoral; e estabelecer o regimento. As decisões são tomadas por maioria de 2/3 dos membros. O Comitê poderá criar grupos técnicos paritários. A participação é serviço público relevante, não remunerado.', '["Composição: três do Executivo federal, três do TSE, um da Câmara, um do Senado e um do CNJ.","Recomenda padrões e diretrizes e orienta a interoperabilidade.","Decisões por maioria de 2/3.","Participação não remunerada."]'::jsonb, '["ATUALIZAÇÃO: uma das alíneas do inciso I do §2º foi revogada pela Lei nº 14.534, de 2023.","Maioria de 2/3 para decidir."]'::jsonb, 'O Comitê recomenda o padrão biométrico da ICN.', '["Assertiva que fixa maioria simples nas decisões do Comitê erra: é de 2/3."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'icn' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É instituído o Fundo da Identificação Civil Nacional (FICN), de natureza contábil, gerido pelo Tribunal Superior Eleitoral, para constituir fonte de recursos para o desenvolvimento e a manutenção da ICN e das bases por ela utilizadas. Constituem recursos do FICN os do orçamento da União, o resultado de aplicações financeiras, a receita do serviço de conferência de dados e outros recursos, como convênios e doações. O saldo positivo é transferido para o exercício seguinte. O FICN deverá garantir o funcionamento, a integração, a padronização e a interoperabilidade das bases biométricas no âmbito da União.', '["Fundo contábil gerido pelo TSE.","Recursos: orçamento da União, aplicações, conferência de dados, convênios e doações.","Saldo positivo passa ao exercício seguinte."]'::jsonb, '["Os recursos do orçamento da União não se confundem com os da Justiça Eleitoral."]'::jsonb, 'A receita da conferência biométrica abastece o FICN.', '["Assertiva que atribui a gestão do FICN ao Ministério da Fazenda erra: é do TSE."]'::jsonb, '[{"termo":"FICN","significado":"Fundo da Identificação Civil Nacional."}]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'icn' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Tribunal Superior Eleitoral estabelecerá cronograma das etapas de implementação da ICN e de coleta das informações biométricas.', '["Cronograma de implementação e coleta definido pelo TSE."]'::jsonb, '["O cronograma é do TSE."]'::jsonb, 'O TSE define as etapas de coleta biométrica.', '["Assertiva que atribui o cronograma ao Poder Executivo erra: é do TSE."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'icn' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É criado o Documento Nacional de Identidade (DNI), com fé pública e validade em todo o território nacional, que faz prova de todos os dados nele incluídos. Será emitido pela Justiça Eleitoral, pelos institutos de identificação civil dos Estados e do Distrito Federal, com certificação da Justiça Eleitoral, ou por outros órgãos, mediante delegação do TSE e com certificação da Justiça Eleitoral. Poderá substituir o título de eleitor, conforme regulamento do TSE. Nos novos DNIs será adotado o CPF como número único.', '["DNI com fé pública e validade nacional.","Faz prova dos dados nele incluídos.","Emissão pela Justiça Eleitoral, institutos estaduais ou outros órgãos delegados.","Pode substituir o título de eleitor.","CPF como número único."]'::jsonb, '["ATUALIZAÇÃO: o §6º (CPF como número único) foi incluído por lei posterior.","Os §§2º e 5º foram vetados."]'::jsonb, 'O DNI emitido pela Justiça Eleitoral pode substituir o título de eleitor.', '["Assertiva que atribui a emissão do DNI exclusivamente aos Estados erra: a Justiça Eleitoral também emite."]'::jsonb, '[{"termo":"DNI","significado":"Documento Nacional de Identidade."}]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'icn' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

