insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público deverá oferecer mecanismos que possibilitem o cruzamento de informações de bases oficiais, a partir do CPF do solicitante, para que a verificação do cumprimento dos requisitos de elegibilidade para a concessão e a manutenção de benefícios sociais possa ser feita pelo órgão concedente.', '["Cruzamento de informações pelo CPF.","Verificação de elegibilidade para benefícios sociais."]'::jsonb, '["O CPF é a chave de cruzamento."]'::jsonb, 'O órgão confere pelo CPF se o beneficiário ainda cumpre os requisitos.', '["Assertiva que impede o cruzamento de dados para benefícios sociais erra."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'icn' and u.unit_key = 'art-11'
