select u.id, u.content_sha256, 'Compete ao Instituto Nacional de Tecnologia da Informação propor à Cefic a regulamentação dos processos de credenciamento, homologação, auditoria e fiscalização de sistemas biométricos, de personalização e de gráficas na expedição da Carteira de Identidade; operacionalizar esses processos; disponibilizar infraestrutura para integração de dados biométricos e biográficos; monitorar e dar suporte técnico; propor estudos sobre tecnologias de identificação; e operacionalizar outras demandas.', '["Credenciamento, homologação, auditoria e fiscalização de sistemas biométricos e gráficas.","Infraestrutura para integração de dados.","Suporte técnico e estudos."]'::jsonb, '["Quem credencia e fiscaliza sistemas biométricos e gráficas: ITI."]'::jsonb, 'O ITI homologa a gráfica que produz as carteiras.', '["Assertiva que atribui ao ITI a coordenação da Cefic erra."]'::jsonb, '[{"termo":"ITI","significado":"Instituto Nacional de Tecnologia da Informação."}]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-20'
