select u.id, u.content_sha256, 'Compete ao Ministério da Justiça e Segurança Pública a implementação, gestão e sustentação da base de dados de identificação e cadastrais obtidos dos órgãos de identificação dos entes federativos e da administração federal; a implementação, gestão e sustentação na confecção e leitura do QR code e dos formulários dos modelos físicos da carteira; e a coordenação, por meio da Secretaria Nacional de Segurança Pública, com auxílio da Cefic, da aquisição dos objetos necessários junto aos entes federativos, com recursos do Fundo Nacional de Segurança Pública ou de outras fontes. A tecnologia do QR code poderá ser usada por outras entidades.', '["Base de dados de identificação e cadastrais.","QR code e formulários físicos.","Aquisição de objetos junto aos entes com recursos do Fundo Nacional de Segurança Pública."]'::jsonb, '["Aquisição coordenada pela Secretaria Nacional de Segurança Pública."]'::jsonb, 'O Ministério da Justiça coordena a compra de insumos da carteira com recursos do Fundo Nacional de Segurança Pública.', '["Assertiva que atribui ao Ministério da Gestão a base de dados de identificação erra: é do Ministério da Justiça."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-21'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete à Polícia Federal, no âmbito do Serviço, propor à Cefic padrões técnicos das bases e dos dados biométricos, padrões de documentos de segurança e a regulamentação do procedimento em caso de divergência na verificação dos dados; assessorar na definição de padrões de componentes eletrônicos e aplicativos de identificação digital; subsidiar técnica e operacionalmente a identificação inequívoca nos bancos biométricos; disponibilizar subsídios para acesso à sua base biométrica; e apoiar tecnicamente a auditoria e a fiscalização dos sistemas biométricos.', '["Propõe padrões biométricos e de documentos de segurança.","Assessora identificação digital.","Subsidia identificação inequívoca.","Disponibiliza acesso à base biométrica.","Apoia auditoria dos sistemas biométricos."]'::jsonb, '["A PF PROPÕE e apoia; quem edita as normas é a Cefic."]'::jsonb, 'A PF propõe o padrão técnico dos dados biométricos.', '["Assertiva que atribui à PF a edição final das normas erra: ela propõe à Cefic."]'::jsonb, '[]'::jsonb, '["Art. 10"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-22'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete à Receita Federal gerir, disciplinar, monitorar e estabelecer padrões, critérios e normas para os atos cadastrais do CPF por meio do Serviço: inscrição, alteração de dados, suspensão, regularização, cancelamento, anulação e demais atos de integração com outras administrações tributárias e organismos internacionais. Assessora tecnicamente a Cefic nas questões do CPF, analisa e decide divergências nos dados cadastrais da base do CPF e responde pela integração dos dados para emissão da carteira com os da inscrição no CPF.', '["Atos cadastrais do CPF: inscrição, alteração, suspensão, regularização, cancelamento e anulação.","Assessoria técnica à Cefic.","Decide divergências na base do CPF.","Integração dos dados da carteira com o CPF."]'::jsonb, '["Quem decide divergências no CPF é a Receita Federal."]'::jsonb, 'A Receita decide o conflito entre dois cadastros do mesmo CPF.', '["Assertiva que atribui à Polícia Federal a gestão do CPF erra: é da Receita Federal."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'sic' and u.unit_key = 'art-23'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O artigo altera o Decreto que regulamenta a Carteira de Identidade, em especial os arts. 3º, 20, 21, 22 e 24, para prever a inscrição de ofício no CPF, a condição de integração com o Serviço, o acesso ao banco do CPF sem convênio, a substituição do sistema nacional anterior pelo Serviço e a obrigatoriedade dos padrões a partir de janeiro de 2024.', '["Altera o Decreto da Carteira de Identidade.","Inscrição de ofício no CPF.","Acesso ao CPF sem convênio.","Serviço substitui o sistema nacional anterior.","Padrões obrigatórios a partir de janeiro de 2024."]'::jsonb, '["ATUALIZAÇÃO: este dispositivo modifica o Decreto da CIN; confira a redação vigente."]'::jsonb, 'A obrigação de seguir os padrões nacionais passa a valer em janeiro de 2024.', '["Assertiva que mantém inalterado o Decreto da Carteira de Identidade erra: ele foi alterado."]'::jsonb, '[]'::jsonb, '["Decreto da CIN"]'::jsonb, 'under_review', 'claude'
